// WP-38 slice 3: FinePrint.ContractDefs (Assembly-CSharp/FinePrint/ContractDefs.cs), the full static class: the typed defaults of every
// contract section (contract_defs_members.inc, generated), the defaults writer CreateDefaultConfig (+ the PART_REQUEST / RESOURCE_REQUEST /
// CREW_REQUEST / SURVEY_DEFINITION node builders), LoadConfig (the Contracts.cfg reader), Awake / LoadDefinitions and the registry that
// lets ContractDefsLite (contracts/contract_environment.hpp) answer from the typed members.
//
// The static members, the writer and the reader are generated by tools/wp38c/gen_contract_defs.py (a line transliteration of the C#; the
// C# member path is the C++ path with `::`). The MonoBehaviour plumbing (instance GameObject, GameEvents subscription, sprites) is not ported.
#pragma once

#include <memory>
#include <string>
#include <variant>
#include <vector>

#include <functional>
#include <utility>

#include "ksp/config/config_node.hpp"
#include "ksp/fineprint/prebuilt.hpp"

namespace ksp::FinePrint {

// FinePrint/ContractDefs.cs:11
struct ContractDefs {
#include "ksp/fineprint/contract_defs_members.inc"

    // ContractDefs.cs:1292 / :1296 / 1298 / 1300 / 1302
    static inline ConfigNode::NodePtr config;
    static inline const std::string textureBaseUrl = "Squad/Contracts/Icons/";
    static inline const std::string configPath = "GameData/Squad/Contracts/Contracts.cfg";
    // KSPUtil.ApplicationRootPath (the game folder, with a trailing separator). Unset: "" (paths relative to the working directory).
    static inline std::string applicationRootPath;

    // ---- C# members that are not part of the generated list ----
    // ContractDefs.cs:1304-1316 (the objective names)
    static constexpr const char* ObjectiveAntenna = "Antenna";
    static constexpr const char* ObjectiveBattery = "Battery";
    static constexpr const char* ObjectiveDock = "Dock";
    static constexpr const char* ObjectiveGenerator = "Generator";
    static constexpr const char* ObjectiveGrapple = "Grapple";
    static constexpr const char* ObjectiveWheel = "Wheel";

    // ---- the pre-built craft data (ContractDefs.cs:1290-1294 / :1438-1560) ----
    using PositionList = std::vector<Contracts::Lite::PreBuiltCraftPosition>;
    // DictionaryValueList<string, List<PreBuiltCraftPosition>>: insertion ordered, ContainsKey / indexer by body name
    struct PositionDictionary {
        std::vector<std::pair<std::string, PositionList>> items;
        bool ContainsKey(const std::string& key) const;
        PositionList& operator[](const std::string& key);
        PositionList* TryGetValue(const std::string& key);
    };
    static inline std::shared_ptr<Contracts::Lite::PreBuiltCraft> PreBuiltCraftDefs;          // :1290
    static inline PositionDictionary PreBuiltCraftPositions;                                 // :1292
    static inline std::shared_ptr<Contracts::Lite::ConstructionParts> constructionParts;     // :1294
    static inline bool loadedContractCraftDefs = false;                                      // :1298
    static inline bool loadedConstructionPartsList = false;                                  // :1300
    // GameDatabase.Instance.GetConfigNodes(typeName). Unset: the GameDatabase singleton (none: no nodes).
    static inline std::function<std::vector<ConfigNode*>(const std::string& typeName)> gameDatabaseConfigNodes;
    static void LoadContractCraftDefs();                                                    // :1438
    static void LoadConstructionPartsList();                                                // :1455
    static std::shared_ptr<Contracts::Lite::PreBuiltCraft> GetPreBuiltCraft(const std::string& className, const ConfigNode& node);  // :1503
    static PositionDictionary GetPreBuiltCraftPositions(const ConfigNode& node);            // :1535
    // ContractDefs.TechResearched (:1432): the loaded craft definitions are reloaded after any research
    static void TechResearched();

    // ---- the registry (C++ helper) ----
    using Ptr = std::variant<int*, float*, double*, bool*, std::string*>;
    struct Entry {
        const char* section;  // cfg node below "Contracts" ("" for the top level keys)
        const char* sub;      // cfg sub node ("Expiration", "Funds", ..., "" for none)
        const char* key;
        Ptr member;
        bool serenityOnly;    // read only when ExpansionsLoader.IsExpansionInstalled("Serenity")
    };
    static const std::vector<Entry>& Registry();
    struct Named {
        const char* path;  // the C# member path, e.g. "ARM.Expire.MinimumExpireDays"
        Ptr member;
    };
    static const std::vector<Named>& AllMembers();
    // the member behind (section, sub, key) or nullptr
    static const Entry* Find(const std::string& section, const std::string& sub, const std::string& key);

    // ---- functions ----
    // C++ helper: every member back to its C# initialiser
    static void ResetToDefaults();
    // ContractDefs.cs:1562 (writes `applicationRootPath + configPath` and leaves `config` = the Contracts node)
    static void CreateDefaultConfig();
    // ContractDefs.cs:2072 (reads `config`)
    static void LoadConfig();
    // ContractDefs.cs:1401 Awake: config = the union of the "Contracts" nodes of the GameDatabase (CopyTo), CreateDefaultConfig when the cfg file does
    // not exist (`cfgFileExists`), LoadConfig, LoadDefinitions. Starts from the C# defaults.
    static void Awake(const std::vector<const ConfigNode*>& contractsNodes, bool cfgFileExists);
    // ContractDefs.cs:1387
    static void LoadDefinitions();

private:
    // ContractDefs.cs:2819 / :2972 / :3254 / :3429
    static void AddSurveyDefinitions(ConfigNode* surveyNode);
    static void AddPartRequests(ConfigNode* topNode);
    static void AddResourceRequests(ConfigNode* topNode);
    static void AddCrewRequests(ConfigNode* topNode);
};

}  // namespace ksp::FinePrint
